package com.csust.eyediagnosis.workflow.evidence;
import org.junit.jupiter.api.Test; import java.util.List; import java.util.Set; import static org.junit.jupiter.api.Assertions.*;
class RetrievalSourceValidatorTest { @Test void retainsLegalCitationAndRejectsEveryGovernanceViolation() { EvidenceCandidate valid = EvidenceFixtures.candidate(); EvidenceCandidate privateSource = EvidenceFixtures.candidate(KnowledgeVisibility.PRIVATE_USER, KnowledgeReviewStatus.APPROVED, false, "p", "r", "c", "q", Set.of("amd"), Set.of("DISEASE_OVERVIEW")); EvidenceCandidate pending = EvidenceFixtures.candidate(KnowledgeVisibility.CURATED_PUBLIC, KnowledgeReviewStatus.PENDING, false, "p2", "r", "c", "q", Set.of("amd"), Set.of("DISEASE_OVERVIEW")); EvidenceCandidate withdrawn = EvidenceFixtures.candidate(KnowledgeVisibility.CURATED_PUBLIC, KnowledgeReviewStatus.APPROVED, true, "p3", "r", "c", "q", Set.of("amd"), Set.of("DISEASE_OVERVIEW")); EvidenceCandidate badDigest = new EvidenceCandidate("d", "r", "c", "t", "quote", "bad", Set.of("amd"), Set.of("DISEASE_OVERVIEW"), KnowledgeVisibility.CURATED_PUBLIC, KnowledgeReviewStatus.APPROVED, false, .1, java.util.Map.of()); ValidatedEvidenceBatch batch = new DefaultRetrievalSourceValidator(new FixedEvidenceTermCatalog()).validate(EvidenceFixtures.intent(), new EvidenceRetrievalBatch(EvidenceFixtures.intent(), EvidenceFixtures.query(), List.of(valid, privateSource, pending, withdrawn, badDigest, valid), false)); assertEquals(1, batch.citations().size()); assertTrue(batch.failures().containsAll(Set.of(RetrievalValidationFailure.INVALID_VISIBILITY, RetrievalValidationFailure.INVALID_REVIEW_STATUS, RetrievalValidationFailure.WITHDRAWN_SOURCE, RetrievalValidationFailure.DIGEST_MISMATCH, RetrievalValidationFailure.DUPLICATE_CITATION))); } }
